// adj maps a node id to its neighbours.
bool mColoring(const std::vector<std::string>& nodes,
               const std::map<std::string, std::vector<std::string>>& adj,
               int m,
               std::map<std::string, int>& colors) {

    auto canUse = [&](const std::string& node, int color) {
        auto it = adj.find(node);
        if (it == adj.end()) return true;
        for (const auto& nb : it->second) {
            auto c = colors.find(nb);
            if (c != colors.end() && c->second == color) return false;
        }
        return true;
    };

    std::function<bool(size_t)> backtrack = [&](size_t i) -> bool {
        if (i == nodes.size()) return true;     // every node coloured

        const std::string& node = nodes[i];
        for (int c = 0; c < m; c++) {
            if (!canUse(node, c)) continue;     // prune: a neighbour already has c

            colors[node] = c;                   // choose
            if (backtrack(i + 1)) return true;  // explore, stop at first success
            colors.erase(node);                 // un-choose
        }

        return false;                           // no colour worked here
    };

    return backtrack(0);
}
